// Mira Knowledge Base: embedded project data + deterministic FACTS.
// Code computes counts, filters and dates so the LLM agents never have to.
// To use another project, replace the four data blocks below.

const cfg = $('Config').first().json;

// ---------- Embedded project data (generated from Resources/) ----------
const PROJECT_NAME = 'AI Adoption Project – ABCDE Ltd.';
const PROJECT_DESCRIPTION = `AI Adoption Project Description for ABCDE Ltd.

ABCDE Ltd., a mid-sized enterprise specializing in logistics and supply chain solutions, is embarking on an AI adoption initiative to enhance operational efficiency, improve customer experience, and drive data-driven decision-making across the organization. This project will focus on integrating AI-powered tools into core business functions, including demand forecasting, route optimization, inventory management, and customer support. By leveraging machine learning models and natural language processing, the company aims to reduce manual overhead, minimize errors, and uncover actionable insights from historical and real-time data.

The AI adoption project will be implemented in phases, beginning with a detailed assessment of current workflows and data infrastructure, followed by pilot implementations in targeted departments. Key goals include reducing delivery delays by 15%, lowering operational costs by 10%, and improving service responsiveness. A cross-functional task force comprising data scientists, IT professionals, and business stakeholders will oversee the deployment and ensure alignment with organizational objectives. This strategic move is expected to position ABCDE Ltd. as a technology-forward leader in the logistics industry.`;
const TIMELINE_CSV = `phase,phase_name,start_week,end_week,key_activities,milestones_deliverables
1,Project Initiation,1,2,"Define project scope; Form cross-functional team; Initial stakeholder meeting","Project charter signed off; Team structure finalized"
2,Current State Analysis,3,4,"Assess existing processes & systems; Identify data sources & gaps","Current systems audit report; Gap analysis report"
3,Use Case Selection,5,6,"Shortlist priority AI use cases (forecasting, route optimization)","Final list of prioritized use cases with success criteria"
4,Pilot Design,7,10,"Data collection & preparation; Model design and development","Working prototype models; Data pipelines established"
5,Pilot Implementation,11,14,"Deploy AI models in test environments; Monitor performance","Pilot results report; User feedback and performance metrics"
6,Evaluation & Iteration,15,16,"Evaluate pilot outcomes; Adjust models as needed","Updated models and process refinements"
7,Full Deployment,17,22,"Scale AI models across selected departments; Train staff","Full production rollout; Training sessions completed"
8,Monitoring & Review,23,24,"Continuous performance monitoring; Final project review","Project closure report; Recommendations for future scaling"`;
const RISKS_CSV = `risk_id,category,risk_challenge,impact,mitigation_strategy
R01,Data Quality & Availability,Incomplete or unstructured data,Poor model performance and inaccurate outcomes,Perform early data audits and implement robust data governance
R02,Integration Issues,Difficulty integrating AI with legacy systems,Delays in deployment and operational disruptions,Plan integration roadmap and use APIs/middleware
R03,Talent & Skills Gap,Lack of internal AI/ML expertise,Overreliance on external vendors and slow progress,Provide staff training and hire specialized talent
R04,Change Resistance,Employees resist adopting AI-driven workflows,Low adoption and reduced ROI,Strong change management and early engagement
R05,Ethical & Legal Concerns,Risks of biased models or data privacy violations,Legal repercussions and reputational damage,Involve legal early and implement fairness checks
R06,Cost Overruns,Underestimation of AI development costs,Budget constraints and project delays,Set realistic budget and build in contingency funds
R07,Unrealistic Expectations,Stakeholders expect immediate ROI,Disillusionment and loss of support,Align expectations and show quick wins
R08,Model Performance Drift,AI models lose accuracy over time,Incorrect decisions and trust erosion,Regular retraining cycles and monitoring dashboards
R09,Security Vulnerabilities,AI models targeted by adversarial attacks,Data breaches and operational risks,Adopt AI security best practices and penetration testing
R10,Vendor Lock-in,Overdependence on a specific AI platform,Flexibility loss and future switching costs,Favor open standards and negotiate flexible vendor terms`;
const TASKS_CSV = `task_id,task_name,status,assignee,priority,sprint,due_date,labels,description
T001,Define project scope and objectives,Done,Arjun Mehta,High,Sprint 1,2026-04-07,Planning,"Document project scope, goals, and success criteria for AI adoption"
T002,Form cross-functional task force,Done,Sarah Lin,High,Sprint 1,2026-04-07,Planning,"Identify and onboard team members from data science, IT, and business units"
T003,Initial stakeholder alignment meeting,Done,Arjun Mehta,High,Sprint 1,2026-04-10,Planning,"Present project charter and get sign-off from leadership"
T004,Audit existing data infrastructure,Done,Priya Nair,High,Sprint 2,2026-04-18,Analysis,"Assess current databases, data pipelines, and data quality"
T005,Map current logistics workflows,Done,James Wong,Medium,Sprint 2,2026-04-18,Analysis,"Document end-to-end processes for demand forecasting, routing, and inventory"
T006,Identify data gaps and quality issues,In Progress,Priya Nair,High,Sprint 2,2026-04-21,Analysis,"Gap analysis report comparing available data vs requirements for AI models"
T007,Shortlist AI use cases,In Progress,Arjun Mehta,High,Sprint 3,2026-04-28,Use Cases,"Evaluate and prioritize: demand forecasting, route optimization, inventory mgmt, customer support"
T008,Define success criteria for each use case,To Do,Sarah Lin,High,Sprint 3,2026-05-02,Use Cases,"Set measurable KPIs: 15% reduction in delivery delays, 10% cost reduction"
T009,Vendor evaluation for ML platform,To Do,James Wong,Medium,Sprint 3,2026-05-05,Use Cases,"Compare cloud ML platforms (AWS SageMaker, Azure ML, GCP Vertex AI)"
T010,Collect historical demand data,To Do,Priya Nair,High,Sprint 4,2026-05-12,Data Prep,"Extract 2 years of demand data from ERP system"
T011,Data cleaning and preprocessing pipeline,To Do,Priya Nair,High,Sprint 4,2026-05-19,Data Prep,"Build automated pipeline for data cleaning, normalization, feature engineering"
T012,Design demand forecasting model,To Do,Ravi Kumar,High,Sprint 4,2026-05-19,Model Dev,"Select algorithm (LSTM, Prophet, XGBoost), define input features"
T013,Design route optimization model,To Do,Ravi Kumar,Medium,Sprint 5,2026-05-26,Model Dev,"Graph-based optimization with constraints (time windows, vehicle capacity)"
T014,Build model training pipeline,To Do,Ravi Kumar,High,Sprint 5,2026-06-02,Model Dev,"Automated training, validation, and model versioning"
T015,Deploy demand model to test environment,To Do,James Wong,High,Sprint 6,2026-06-09,Pilot,"Deploy to staging, set up monitoring, define test scenarios"
T016,Run pilot with logistics team,To Do,Arjun Mehta,High,Sprint 6,2026-06-16,Pilot,"2-week pilot with 3 logistics coordinators using demand forecasting predictions"
T017,Collect pilot feedback and metrics,To Do,Sarah Lin,High,Sprint 7,2026-06-23,Evaluation,"Survey users, measure prediction accuracy, compare with manual forecasts"
T018,Iterate on model based on feedback,To Do,Ravi Kumar,Medium,Sprint 7,2026-06-30,Evaluation,"Adjust features, retrain model, validate improvements"
T019,Prepare production deployment plan,To Do,James Wong,High,Sprint 8,2026-07-07,Deployment,"Infrastructure scaling, rollback plan, monitoring setup"
T020,Staff training program,To Do,Sarah Lin,Medium,Sprint 8,2026-07-14,Deployment,"Train 25 logistics staff on using AI-powered forecasting dashboard"
T021,Full production rollout,To Do,Arjun Mehta,High,Sprint 9,2026-07-21,Deployment,"Go-live for demand forecasting across all 3 distribution centers"
T022,Set up continuous monitoring,To Do,Priya Nair,High,Sprint 9,2026-07-28,Monitoring,"Model performance dashboards, drift detection alerts, retraining triggers"
T023,Project closure report,To Do,Arjun Mehta,Medium,Sprint 10,2026-08-04,Monitoring,"Final report: outcomes vs targets, lessons learned, recommendations for Phase 2"
T024,Security review of AI infrastructure,Blocked,James Wong,High,Sprint 5,2026-05-26,Security,"Penetration testing and vulnerability assessment - BLOCKED: waiting for security team availability"
T025,Legal review of data usage,In Progress,Sarah Lin,High,Sprint 3,2026-04-28,Compliance,"Review data privacy compliance for using customer delivery data in ML models"`;

// ---------- Helpers ----------
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((v) => v.trim() !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((v) => v.trim() !== '')) rows.push(row);
  const [header, ...body] = rows;
  return body.map((r) => Object.fromEntries(header.map((h, i) => [h.trim(), (r[i] ?? '').trim()])));
}

const DAY = 86400000;
const toDate = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)); };
const fmt = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * DAY);
const daysBetween = (a, b) => Math.round((b - a) / DAY);
const countBy = (arr, key) => arr.reduce((acc, x) => ({ ...acc, [x[key]]: (acc[x[key]] ?? 0) + 1 }), {});

const asOf = toDate(cfg.asOfDate);
const projectStart = toDate(cfg.projectStartDate);
const upcomingEnd = addDays(asOf, Number(cfg.upcomingWindowDays));
const dueSoonEnd = addDays(asOf, Number(cfg.dueSoonDays));
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

// ---------- Timeline: week numbers -> calendar dates ----------
const timeline = parseCsv(TIMELINE_CSV).map((p) => {
  const start = addDays(projectStart, (Number(p.start_week) - 1) * 7);
  const end = addDays(projectStart, Number(p.end_week) * 7 - 1);
  const status = end < asOf ? 'Completed (by schedule)' : start > asOf ? 'Upcoming' : 'Current';
  return {
    phase: Number(p.phase),
    phase_name: p.phase_name,
    start_week: Number(p.start_week),
    end_week: Number(p.end_week),
    start_date: fmt(start),
    end_date: fmt(end),
    schedule_status: status,
    key_activities: p.key_activities.split(';').map((s) => s.trim()).filter(Boolean),
    milestones: p.milestones_deliverables.split(';').map((s) => s.trim()).filter(Boolean),
  };
});

// Each milestone is due at the end of its phase.
const milestones = timeline.flatMap((p) => p.milestones.map((m) => ({
  milestone: m,
  phase: p.phase,
  phase_name: p.phase_name,
  due_week: p.end_week,
  due_date: p.end_date,
  days_from_as_of: daysBetween(asOf, toDate(p.end_date)),
})));

// ---------- Project outcome phrases ----------
// Short verbatim phrases from the description (goals, use cases, capabilities). Agents cite these
// from a fixed list instead of free-text quoting, so a citation can never be invented.
const LEAD = /^(and|or|including|include|includes|the company aims to|aims to|by leveraging|by|to|of|with|is embarking on an ai adoption initiative to|key goals include|this project will focus on|beginning with|followed by|will)\s+/i;
const outcomePhrases = [...new Set(PROJECT_DESCRIPTION.split('\n').slice(1).join(' ')
  .split(/[.;,]|\s+and\s+(?=[a-z]+ing\b|improv|reduc|lower|minim|uncov|drive|enhanc)/)
  .map((s) => { let t = s.trim(), prev; do { prev = t; t = t.replace(LEAD, ''); } while (t !== prev); return t; })
  .filter((s) => { const n = s.split(/\s+/).length; return n >= 2 && n <= 9 && !/ABCDE|^This|^The /.test(s); }))];
const USE_CASES = ['demand forecasting', 'route optimization', 'inventory management', 'customer support']
  .filter((u) => PROJECT_DESCRIPTION.toLowerCase().includes(u));

// ---------- Risks ----------
const risks = parseCsv(RISKS_CSV);

// ---------- Tasks ----------
const tasks = parseCsv(TASKS_CSV).map((t) => {
  const due = toDate(t.due_date);
  return { ...t, days_until_due: daysBetween(asOf, due) };
});
const open = (t) => t.status !== 'Done';

const statusCounts = Object.fromEntries(STATUSES.map((s) => [s, tasks.filter((t) => t.status === s).length]));
const unknownStatuses = tasks.filter((t) => !STATUSES.includes(t.status)).map((t) => `${t.task_id}: ${t.status}`);

const sprintNames = [...new Set(tasks.map((t) => t.sprint))]
  .sort((a, b) => Number(a.replace(/\D/g, '')) - Number(b.replace(/\D/g, '')));
const sprints = sprintNames.map((name) => {
  const ts = tasks.filter((t) => t.sprint === name);
  const dues = ts.map((t) => t.due_date).sort();
  return {
    sprint: name,
    first_due: dues[0],
    last_due: dues[dues.length - 1],
    task_count: ts.length,
    status_counts: Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length])),
    task_ids: ts.map((t) => t.task_id),
  };
});
// Current sprint = first sprint whose last due date has not passed.
const currentSprint = (sprints.find((s) => toDate(s.last_due) >= asOf) ?? sprints[sprints.length - 1]).sprint;

const brief = (t) => ({
  task_id: t.task_id, task_name: t.task_name, status: t.status, assignee: t.assignee,
  priority: t.priority, sprint: t.sprint, due_date: t.due_date, days_until_due: t.days_until_due,
});

const blocked = tasks.filter((t) => t.status === 'Blocked').map((t) => ({ ...brief(t), description: t.description }));
const overdue = tasks.filter((t) => open(t) && toDate(t.due_date) < asOf).map(brief);
const dueSoon = tasks.filter((t) => open(t) && t.status !== 'Blocked'
  && toDate(t.due_date) >= asOf && toDate(t.due_date) <= dueSoonEnd).map(brief);

const workload = Object.entries(countBy(tasks.filter(open), 'assignee'))
  .map(([assignee, open_tasks]) => ({
    assignee,
    open_tasks,
    open_high_priority: tasks.filter((t) => open(t) && t.assignee === assignee && t.priority === 'High').length,
    in_progress: tasks.filter((t) => t.status === 'In Progress' && t.assignee === assignee).map((t) => t.task_id),
  }))
  .sort((a, b) => b.open_tasks - a.open_tasks);

const currentWeek = Math.floor(daysBetween(projectStart, asOf) / 7) + 1;
const currentPhase = timeline.find((p) => p.schedule_status === 'Current') ?? null;

const facts = {
  as_of_date: fmt(asOf),
  project_start_date: fmt(projectStart),
  current_week: currentWeek,
  total_weeks: Math.max(...timeline.map((p) => p.end_week)),
  current_phase: currentPhase ? `Phase ${currentPhase.phase}: ${currentPhase.phase_name}` : 'None (outside timeline)',
  current_sprint: currentSprint,
  total_tasks: tasks.length,
  status_counts: statusCounts,
  completion_pct: Math.round((statusCounts.Done / tasks.length) * 100),
  blocked_tasks: blocked,
  overdue_tasks: overdue,
  due_soon_tasks: dueSoon,
  due_soon_window: `${fmt(asOf)} to ${fmt(dueSoonEnd)}`,
  upcoming_milestones: milestones.filter((m) => m.days_from_as_of >= 0 && toDate(m.due_date) <= upcomingEnd),
  upcoming_window: `${fmt(asOf)} to ${fmt(upcomingEnd)}`,
  next_milestones_after_window: milestones.filter((m) => toDate(m.due_date) > upcomingEnd).slice(0, 2),
  sprints,
  workload,
  risk_count: risks.length,
  risk_categories: risks.map((r) => `${r.risk_id} ${r.category}`),
  data_warnings: unknownStatuses.map((s) => `Unrecognised task status: ${s}`),
};

return [{
  json: {
    project: { name: PROJECT_NAME, description: PROJECT_DESCRIPTION.trim(), outcome_phrases: outcomePhrases, use_cases: USE_CASES },
    timeline,
    milestones,
    risks,
    tasks,
    facts,
  },
}];

// Verifies Knowledge Base FACTS against values hand-counted from the ABCDE Ltd CSVs.
// Specific to the provided sample data; update the expectations if the data changes.

const kb = $input.first().json;
const f = kb.facts;
const ids = (list) => list.map((t) => t.task_id ?? t.milestone).join(', ');

const checks = [
  ['Total tasks = 25', f.total_tasks === 25, f.total_tasks],
  ['Done = 5', f.status_counts.Done === 5, f.status_counts.Done],
  ['In Progress = 3', f.status_counts['In Progress'] === 3, f.status_counts['In Progress']],
  ['Blocked = 1', f.status_counts.Blocked === 1, f.status_counts.Blocked],
  ['To Do = 16', f.status_counts['To Do'] === 16, f.status_counts['To Do']],
  ['Blocked task is T024', ids(f.blocked_tasks) === 'T024', ids(f.blocked_tasks)],
  ['T006 is overdue', f.overdue_tasks.some((t) => t.task_id === 'T006'), ids(f.overdue_tasks)],
  ['Risks = 10 (R01–R10)', kb.risks.length === 10, kb.risks.length],
  ['Timeline phases = 8', kb.timeline.length === 8, kb.timeline.length],
  ['Current week = 4', f.current_week === 4, f.current_week],
  ['Current sprint = Sprint 3', f.current_sprint === 'Sprint 3', f.current_sprint],
  ['Sprint 2 has 3 tasks (T004–T006)', ids(f.sprints.find((s) => s.sprint === 'Sprint 2').task_ids.map((task_id) => ({ task_id }))) === 'T004, T005, T006',
    f.sprints.find((s) => s.sprint === 'Sprint 2').task_ids.join(', ')],
  ['No unrecognised statuses', f.data_warnings.length === 0, f.data_warnings.join('; ') || 'none'],
];

const results = checks.map(([check, pass, actual]) => ({ check, result: pass ? 'PASS' : 'FAIL', actual: String(actual) }));
const failed = results.filter((r) => r.result === 'FAIL').length;

return [{
  json: {
    summary: failed === 0 ? `ALL ${results.length} CHECKS PASSED` : `${failed} of ${results.length} CHECKS FAILED`,
    as_of_date: f.as_of_date,
    results,
  },
}];
